import nbformat
from nbclient import NotebookClient
nb=nbformat.read('modelo_medicina.ipynb', as_version=4)
client=NotebookClient(nb, timeout=420, kernel_name='python3', allow_errors=False)
client.execute()
nbformat.write(nb, 'modelo_medicina_executed.ipynb')
print('NBCLIENT_OK')
# Print selected stage 7 outputs
for i,c in enumerate(nb.cells):
    if i >= 84 and c.cell_type == 'code':
        texts=[]
        for out in c.get('outputs',[]):
            if out.output_type=='stream':
                texts.append(out.text.strip())
            elif out.output_type in ('execute_result','display_data') and 'text/plain' in out.get('data',{}):
                t=out['data']['text/plain']
                if isinstance(t,list): t=''.join(t)
                texts.append(t.strip()[:1200])
        if texts:
            print('\nCELL',i)
            print('\n'.join(texts)[:2000])
